// Data generated by scripts/build-data.ts. Run `npm run data` if these imports fail.
import areasJson from './areas.json';
import fishJson from './fish.json';
import furnitureJson from './furniture.json';
import collectionsJson from './furnitureCollections.json';
import type { Area, Fish, FurnitureCollection, FurnitureItem } from './types';

// shape is validated by build-data.ts; the inferred JSON type is too literal to cast directly
export const FISH = fishJson as unknown as Fish[];
export const AREAS = areasJson as Area[];
export const FISH_IDS: ReadonlySet<string> = new Set(FISH.map(f => f.id));
export const FURNITURE = furnitureJson as unknown as FurnitureItem[];
export const COLLECTIONS = collectionsJson as unknown as FurnitureCollection[];
export const FURNITURE_IDS: ReadonlySet<string> = new Set(FURNITURE.map(f => f.id));

/** Asset paths always go through BASE_URL (GitHub Pages serves from /<repo>/). */
export const fishImage = (id: string) => `${import.meta.env.BASE_URL}fish/${id}.webp`;
export const furnitureImage = (id: string) => `${import.meta.env.BASE_URL}furniture/${id}.webp`;
export const badgeImage = (collectionId: string) => `${import.meta.env.BASE_URL}furniture/sets/${collectionId}.webp`;

export const isBackyard = (f: Fish) => f.areas.includes('backyard');
